import java.util.Scanner;
public class JCheckAge2 {
	public static void main(String[] args) {
		JCheckAge2 jca = new JCheckAge2();
		jca.checkAge();
	}
	// Paso 1: Definir el metodo que procesa la cadena de entrada
	public void checkAge() {
		// Paso 1.1: Pedir una entrada valida mientras la entrada no pueda ser procesada; si no, detener
		Scanner scan = new Scanner(System.in);
		boolean processed = false;
		while ( ! processed ) {
			System.out.println("Ingrese el nombre y la edad, separados por dos puntos:");
			String s = scan.next();
			// Paso 1.1.1: Dividir la cadena dada en nombre y edad
			String[] lst = s.split(":");
			// Paso 1.1.2: Encerrar el codigo que puede lanzar una excepcion dentro del bloque try
			try {
				String name = lst[0];
				int age = Integer.parseInt(lst[1]);
				if ( age >= 13 && age <= 19 ) {           
					System.out.println(name + " es adolescente.");
				} else {          
					System.out.println(name + " no es adolescente.");
				}
	            processed = true;
			}
			// Paso 1.1.3: Manejar todas las posibles excepciones que puedan ser lanzadas en el bloque try 
			catch ( ArrayIndexOutOfBoundsException ex ) {
				System.out.println("Error! Separe el nombre y la edad con dos puntos.");
			} catch ( NumberFormatException ex) {
				System.out.println("Error! La edad debe ser un entero.");
			}
		}	
	}
}

